package com.chatreplacer;

import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;

@ConfigGroup(ChatReplacerConfig.GROUP)
public interface ChatReplacerConfig extends Config
{
	String GROUP = "chat-replacer";

	@ConfigItem(
		keyName = "words",
		name = "Words to replace",
		description = "One word or phrase per line.<br>" +
			"Each line is replaced by the same line number in 'Replace with'.",
		position = 0
	)
	default String words()
	{
		return "";
	}

	@ConfigItem(
		keyName = "replacements",
		name = "Replace with",
		description = "One replacement per line, matching the lines in 'Words to replace'.<br>" +
			"Leave a line empty (or out) to censor that word with asterisks.",
		position = 1
	)
	default String replacements()
	{
		return "";
	}

	@ConfigItem(
		keyName = "caseInsensitive",
		name = "Case insensitive",
		description = "Match words regardless of upper/lower case",
		position = 2
	)
	default boolean caseInsensitive()
	{
		return true;
	}

	@ConfigItem(
		keyName = "matchWholeWords",
		name = "Match whole words only",
		description = "Only match whole words, so a rule for 'ass' won't hit 'class'",
		position = 3
	)
	default boolean matchWholeWords()
	{
		return true;
	}

	@ConfigItem(
		keyName = "replaceOverheadText",
		name = "Replace overhead text",
		description = "Also apply the rules to text shown above players' heads",
		position = 4
	)
	default boolean replaceOverheadText()
	{
		return true;
	}
}

package com.chatreplacer;

import com.google.inject.Provides;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import java.util.regex.Matcher;
import java.util.regex.Pattern;
import java.util.regex.PatternSyntaxException;
import javax.inject.Inject;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.MessageNode;
import net.runelite.api.events.ChatMessage;
import net.runelite.api.events.OverheadTextChanged;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.events.ConfigChanged;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;

@Slf4j
@PluginDescriptor(
	name = "Bink Block",
	description = "Replaces or censors words in chat messages with custom text of your choice",
	tags = {"chat", "filter", "censor", "replace", "word"}
)
public class ChatReplacerPlugin extends Plugin
{
	// Matches formatting tags like <col=ff0000> or <img=41> so rules never rewrite them
	private static final Pattern TAG_PATTERN = Pattern.compile("<[^>]*>");

	@Inject
	private Client client;

	@Inject
	private ChatReplacerConfig config;

	// Replaced wholesale on config change (possibly from the Swing thread), read on the client thread
	private volatile List<Rule> rules = Collections.emptyList();

	private static class Rule
	{
		final Pattern pattern;
		final String replacement; // null means censor with asterisks

		Rule(Pattern pattern, String replacement)
		{
			this.pattern = pattern;
			this.replacement = replacement;
		}
	}

	@Provides
	ChatReplacerConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(ChatReplacerConfig.class);
	}

	@Override
	protected void startUp()
	{
		rebuildRules();
	}

	@Override
	protected void shutDown()
	{
		rules = Collections.emptyList();
	}

	@Subscribe
	public void onConfigChanged(ConfigChanged event)
	{
		if (ChatReplacerConfig.GROUP.equals(event.getGroup()))
		{
			rebuildRules();
		}
	}

	@Subscribe
	public void onChatMessage(ChatMessage event)
	{
		if (rules.isEmpty())
		{
			return;
		}

		MessageNode node = event.getMessageNode();
		String value = node.getValue();
		String replaced = applyRules(value);
		if (!replaced.equals(value))
		{
			node.setValue(replaced);
			client.refreshChat();
		}
	}

	@Subscribe
	public void onOverheadTextChanged(OverheadTextChanged event)
	{
		if (!config.replaceOverheadText() || rules.isEmpty())
		{
			return;
		}

		String text = event.getOverheadText();
		String replaced = applyRules(text);
		if (!replaced.equals(text))
		{
			event.getActor().setOverheadText(replaced);
		}
	}

	private void rebuildRules()
	{
		List<Rule> newRules = new ArrayList<>();
		int flags = config.caseInsensitive() ? Pattern.CASE_INSENSITIVE | Pattern.UNICODE_CASE : 0;

		String[] words = config.words().split("\n", -1);
		String[] replacements = config.replacements().split("\n", -1);

		for (int i = 0; i < words.length; i++)
		{
			String word = words[i].trim();
			if (word.isEmpty())
			{
				continue;
			}

			// Pair line N of the words box with line N of the replacements box;
			// a missing or empty line means censor with asterisks
			String replacement = i < replacements.length ? replacements[i].trim() : null;
			if (replacement != null && replacement.isEmpty())
			{
				replacement = null;
			}

			String regex = Pattern.quote(word);
			if (config.matchWholeWords())
			{
				// Lookarounds instead of \b so rules starting/ending in punctuation still work
				regex = "(?<![\\p{Alnum}])" + regex + "(?![\\p{Alnum}])";
			}

			try
			{
				newRules.add(new Rule(Pattern.compile(regex, flags), replacement));
			}
			catch (PatternSyntaxException ex)
			{
				log.debug("Skipping invalid rule '{}'", word, ex);
			}
		}

		rules = newRules;
	}

	private String applyRules(String value)
	{
		StringBuilder out = new StringBuilder(value.length());
		Matcher tagMatcher = TAG_PATTERN.matcher(value);
		int last = 0;
		while (tagMatcher.find())
		{
			out.append(replaceInText(value.substring(last, tagMatcher.start())));
			out.append(tagMatcher.group());
			last = tagMatcher.end();
		}
		out.append(replaceInText(value.substring(last)));
		return out.toString();
	}

	private String replaceInText(String text)
	{
		if (text.isEmpty())
		{
			return text;
		}

		for (Rule rule : rules)
		{
			Matcher m = rule.pattern.matcher(text);
			if (!m.find())
			{
				continue;
			}

			StringBuffer sb = new StringBuffer(text.length());
			do
			{
				String replacement = rule.replacement != null
					? rule.replacement
					: "*".repeat(m.group().length());
				m.appendReplacement(sb, Matcher.quoteReplacement(replacement));
			}
			while (m.find());
			m.appendTail(sb);
			text = sb.toString();
		}

		return text;
	}
}

package com.chatreplacer;

import net.runelite.client.RuneLite;
import net.runelite.client.externalplugins.ExternalPluginManager;

public class ChatReplacerPluginTest
{
	public static void main(String[] args) throws Exception
	{
		ExternalPluginManager.loadBuiltin(ChatReplacerPlugin.class);
		RuneLite.main(args);
	}
}
